# genex.toml: physics is on unless a table turns it off; a game built on it says so
# (off, every sim.physics call fails to compile: build-failed)
[physics]
enabled = true

// src/facets/yard.rs — the facet's own module; src/main.rs adds its two FACET WIRING lines.
// World (src/main.rs, #[derive(Default)]) holds crates: Vec<String>, bombs: Vec<String>,
// shots: Vec<String>, blasts: u32, pushed: usize, fired: u32, hits: u32 (bodies are keys).
use super::World;
use genex::phys::{self, BodyDesc, BodyType, ColliderDesc, JointDesc, JointType, LimitsDesc, PhysicsEvent, QueryFilter, WorldDesc};
use genex::prelude::*;

/// Crates in the wall: ten wide, ten high, twenty deep.
const CRATES: usize = 2000;
/// The wall's slots that hold a bomb instead of a crate: four in the front, where the ball swings.
const BOMB_SLOTS: [usize; 4] = [44, 45, 54, 55];
/// The wrecking ball's rope, in metres.
const ROPE: f64 = 8.0;
/// Shots kept flying at once (CCD bodies are capped at 16).
const SHOTS_MAX: usize = 8;
/// Where the player shoots from, and at.
const EYE: Vec3 = Vec3::new(0.3, 2.0, 14.0);
const AIM_AT: Vec3 = Vec3::new(0.3, 4.0, -8.0);

/// A body of one collider at `at`.
fn body(key: &str, body_type: BodyType, at: Vec3, collider: ColliderDesc) -> BodyDesc {
    BodyDesc::new(key, body_type, phys::pose(at, Quat::IDENTITY), vec![collider])
}

/// The level: a fixed ground, the wall of crates with its bombs, the trolley and its ball.
fn build(world: &mut World, physics: &mut Physics) {
    let slab = ColliderDesc { friction: Some(0.8), ..ColliderDesc::new("slab", phys::cuboid(vec3(60.0, 0.5, 60.0))) };
    let _ = physics.spawn(&body("ground", BodyType::Fixed, vec3(0.0, -0.5, 0.0), slab));
    for i in 0..CRATES {
        let at = vec3((i % 10) as f32 - 4.5, 0.5 + (i / 10 % 10) as f32, -6.0 - (i / 100) as f32);
        let bomb = BOMB_SLOTS.contains(&i);
        // A bomb reports its contacts (`events`), so the update hook sees what hit it.
        let box_of = ColliderDesc { mass: Some(20.0), friction: Some(0.7), restitution: Some(0.05), events: bomb, ..ColliderDesc::new("box", phys::cuboid(vec3(0.5, 0.5, 0.5))) };
        let key = if bomb { format!("bomb.{i:04}") } else { format!("crate.{i:04}") };
        let _ = physics.spawn(&body(&key, BodyType::Dynamic, at, box_of));
        if bomb { world.bombs.push(key) } else { world.crates.push(key) }
    }
    // The crane: a kinematic trolley over the wall's front; a 600 kg ball hangs from it on a rope.
    let hook = ColliderDesc { sensor: true, ..ColliderDesc::new("hook", phys::ball(0.2)) };
    let _ = physics.spawn(&body("trolley", BodyType::Kinematic, vec3(-12.0, 13.0, -6.0), hook));
    let ball = ColliderDesc { mass: Some(600.0), restitution: Some(0.1), ..ColliderDesc::new("ball", phys::ball(1.0)) };
    let _ = physics.spawn(&BodyDesc { linear_damping: Some(0.05), ..body("ball", BodyType::Dynamic, vec3(-12.0, 5.0, -6.0), ball) });
    let rope = JointDesc { limits: Some([0.0, ROPE]), ..JointDesc::new("rope", "ball", Some("trolley"), JointType::Rope, [0.0; 3], [0.0; 3]) };
    let _ = physics.add_joint(&rope);
}

/// Set off every bomb the last step saw hit by the ball or a shot, or knocked flying: it goes, and
/// pushes what is near.
fn bombs(world: &mut World, physics: &mut Physics) {
    let mut fired: Vec<String> = Vec::new();
    for event in physics.events() {
        let PhysicsEvent::ContactBegin { a, b, .. } = event else { continue };
        for (bomb, other) in [(a, b), (b, a)] {
            let hitter = other == "ball" || world.shots.contains(other);
            if world.bombs.contains(bomb) && hitter && !fired.contains(bomb) {
                fired.push(bomb.clone());
            }
        }
    }
    for bomb in &world.bombs {
        let flying = physics.body(bomb).is_some_and(|state| phys::vec3_of(state.linvel).length() > 6.0);
        if flying && !fired.contains(bomb) {
            fired.push(bomb.clone());
        }
    }
    for bomb in fired {
        let Some(state) = physics.body(&bomb) else { continue };
        let _ = physics.remove(&bomb);
        world.bombs.retain(|key| *key != bomb);
        let near = physics.overlap(&phys::ball(5.0), state.pose, &QueryFilter::default());
        world.pushed += near.map_or(0, |keys| keys.len());
        let _ = physics.area_push(state.pose.p, 5.0, 200.0, 1.0, None);
        world.blasts += 1;
    }
}

/// Fire a CCD shot from the eye: a 10 cm, 30 kg ball at 60 m/s; the ray says what it will hit first.
fn shoot(world: &mut World, physics: &mut Physics) {
    let aim = (AIM_AT - EYE).normalize_or_zero();
    if let Ok(Some(hit)) = physics.ray(phys::xyz(EYE), phys::xyz(aim), 100.0, &QueryFilter::default()) {
        world.hits += u32::from(hit.point[2] < 0.0); // the wall or a bomb, not the ground in front
    }
    if world.shots.len() >= SHOTS_MAX {
        let oldest = world.shots.remove(0);
        let _ = physics.remove(&oldest);
    }
    let key = format!("shot.{}", world.fired);
    let shot = BodyDesc { linvel: Some(phys::xyz(aim * 60.0)), ccd: true, ..body(&key, BodyType::Dynamic, EYE, ColliderDesc { mass: Some(30.0), ..ColliderDesc::new("ball", phys::ball(0.1)) }) };
    if physics.spawn(&shot).is_ok() {
        world.shots.push(key);
        world.fired += 1;
    }
}

pub fn wire(game: &mut Game<World>) {
    // 2,000 crates are past the default 512 bodies: raise the limit (at most 4x, 2,048).
    let limits = LimitsDesc { bodies: Some(2048.0), ..LimitsDesc::default() };
    game.physics_world(WorldDesc { limits, ..phys::default_world() });
    game.on_reset(|sim, _seed, _rng, _gfx| {
        let (world, physics) = sim.split();
        build(world, physics);
    });
    game.on_update(|sim, ctx| {
        let (world, physics) = sim.split();
        // The crane runs the ball through the wall and back every 20 s.
        let phase = (ctx.tick % 1200) as f32 / 600.0;
        let x = -12.0 + 24.0 * (1.0 - (phase - 1.0).abs());
        let _ = physics.set_next_kinematic_pose("trolley", phys::pose(vec3(x, 13.0, -6.0), Quat::IDENTITY));
        bombs(world, physics);
        if ctx.keys.pressed(Key::Space) {
            shoot(world, physics);
        }
    });
    game.on_draw(|sim, frame, _camera| {
        let draw = |frame: &mut Frame, key: &String, size: f32, color: Color| {
            let Some(state) = sim.physics.body(key) else { return };
            let at = Transform::from_translation(phys::vec3_of(state.pose.p)).with_rotation(phys::quat_of(state.pose.q)).with_scale(vec3(size, size, size));
            frame.id(key).cube(at, color);
        };
        frame.tag("crates");
        for key in &sim.world.crates {
            draw(frame, key, 1.0, Color::rgb(170, 120, 70));
        }
        frame.tag("bombs");
        for key in &sim.world.bombs {
            draw(frame, key, 1.0, Color::RED);
        }
        frame.tag("wrecking-ball");
        let at = |key: &str| sim.physics.body(key).map(|state| phys::vec3_of(state.pose.p));
        if let (Some(trolley), Some(ball)) = (at("trolley"), at("ball")) {
            frame.id("wrecking-ball").sphere(ball, 1.0, Color::rgb(60, 60, 70));
            frame.end_id().lines(&[trolley, ball], Color::BLACK);
        }
        frame.end_id();
    });
    // One probe per mechanic, each a few numbers that say whether it works.
    game.probe("pile", |sim| {
        // A crate knocked over: its up axis tipped past 45 degrees.
        let tipped = |key: &String| sim.physics.body(key).is_some_and(|state| (phys::quat_of(state.pose.q) * Vec3::Y).y < 0.7);
        let toppled = sim.world.crates.iter().filter(|key| tipped(key)).count();
        json!({ "crates": sim.world.crates.len(), "toppled": toppled })
    });
    game.probe("blast", |sim| json!({ "bombs": sim.world.bombs.len(), "blasts": sim.world.blasts, "pushed": sim.world.pushed }));
    game.probe("wrecking-ball", |sim| {
        let at = |key: &str| sim.physics.body(key).map(|state| phys::vec3_of(state.pose.p));
        let (trolley, ball) = (at("trolley"), at("ball"));
        let rope = trolley.zip(ball).map(|(t, b)| f64::from((t - b).length()));
        json!({ "onRope": rope.is_some_and(|length| length <= ROPE + 0.05), "low": ball.is_some_and(|b| b.y < 6.0) })
    });
    game.probe("shots", |sim| json!({ "fired": sim.world.fired, "aimedAtWall": sim.world.hits }));
    // A load wakes every body it puts back, so how many are awake is display only.
    game.probe_volatile("awake", |sim| json!(sim.physics.stats().awake));
}
